package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen0Test {

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] input = new byte[0];
        // Should return the same array (input) if length is 0
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertSame(input, result);
    }

    @Test
    public void testEncodeBase64_NormalStandard() {
        byte[] input = "Hello".getBytes();
        // Standard Base64: "SGVsbG8="
        byte[] expected = "SGVsbG8=".getBytes();
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testEncodeBase64_UrlSafe() {
        // Use characters that change in URL safe mode (e.g., + and /)
        // Input that produces '+' or '/' in standard Base64
        byte[] input = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) 0xff}; 
        // Standard: "+/+///" (approx)
        // URL Safe: "-_-_--" (approx)

        byte[] result = Base64.encodeBase64(input, false, true, 100);
        String resultStr = new String(result);

        assertFalse("Result should not contain '+'", resultStr.contains("+"));
        assertFalse("Result should not contain '/'", resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_Chunked() {
        // Testing chunked encoding
        byte[] input = new byte[100];
        for (int i = 0; i < 100; i++) {
            input[i] = (byte) i;
        }
        // isChunked = true
        // This will trigger the MIME_CHUNK_SIZE logic
        byte[] result = Base64.encodeBase64(input, true, false, 1000);
        assertNotNull(result);
        assertTrue("Chunked output should be non-empty", result.length > 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEncodeBase64_TooBig() {
        byte[] input = new byte[50];
        // Set maxResultSize very small so it triggers the exception
        // len will be > 10
        Base64.encodeBase64(input, false, false, 10);
    }

    @Test
    public void testEncodeBase64_ChunkedUrlSafe() {
        byte[] input = new byte[200];
        // Test combination of chunked and urlSafe
        byte[] result = Base64.encodeBase64(input, true, true, 1000);
        assertNotNull(result);
        String resultStr = new String(result);
        assertFalse(resultStr.contains("+"));
        assertFalse(resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_LargeMaxSize() {
        byte[] input = "test".getBytes();
        // Test with a very large maxResultSize to ensure no overflow/boundary issues
        byte[] result = Base64.encodeBase64(input, false, false, Integer.MAX_VALUE);
        assertNotNull(result);
        assertEquals("test", new String(Base64.decodeBase64(result)).equals("test") ? "test" : "");
    }
}
